def reshard(admin,s3,bucket,target_shards):
    if type(target_shards)is not int or not 2<=target_shards<=11:raise ValueError('approved bounded integer shard target required')
    before=admin('bucket','stats','--bucket',bucket)
    if target_shards<before['num_shards']:raise ValueError('this exercise does not approve shrinking')
    before_keys=names(s3,bucket)
    if before['num_shards']!=target_shards:admin('bucket','reshard','--bucket',bucket,'--num-shards',target_shards)
    after=admin('bucket','stats','--bucket',bucket)
    entries={str(i):admin('bi','list','--bucket',bucket,'--shard-id',i)for i in range(target_shards)}
    status=admin('reshard','status','--bucket',bucket)
    return {'before_stats':before,'after_stats':after,'before_keys':before_keys,'after_keys':names(s3,bucket),'shard_entries':entries,'reshard_status':status,'production_performance_certified':False}

