import pathlib,sys,json,secrets,os,time,hashlib,copy,math
sys.path.insert(0,str(pathlib.Path.cwd()/'checks'))
from rgw_native import PrivateRGW,command,record_native
from botocore.session import get_session
from botocore.config import Config
import task
assert os.geteuid()==1000
def canon(value):return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False)
with PrivateRGW()as c:
 s3=c.s3;bucket='s07-shards-'+secrets.token_hex(5);s3.create_bucket(Bucket=bucket);target=secrets.choice((3,5));bodies={};metadata={}
 def native(*args):
  raw=command('radosgw-admin','-c',c.config,'--rgw-data',c.rgw_data,*map(str,args),timeout=35)
  try:value=json.loads(raw)
  except ValueError as error:
   if tuple(args[:2])!=('bucket','reshard'):raise RuntimeError('official read-only diagnostic returned incomplete/non-JSON output')from error
   return raw
  expected=dict if tuple(args[:2])==('bucket','stats')else list
  if tuple(args[:2])!=('bucket','reshard')and type(value)is not expected:raise RuntimeError('official diagnostic JSON has wrong top-level type')
  return value
 def put(key,body):
  meta={'preserve':secrets.token_hex(6)};s3.put_object(Bucket=bucket,Key=key,Body=body,Metadata=meta,ContentType='application/x-s07-small-object');bodies[key]=body;metadata[key]=meta
 def listing(client):
  return sorted(row['Key']for page in client.get_paginator('list_objects_v2').paginate(Bucket=bucket,PaginationConfig={'PageSize':7})for row in page.get('Contents',[]))
 def snapshot():
  result={}
  for key,body in bodies.items():
   got=s3.get_object(Bucket=bucket,Key=key)
   try:assert got['Body'].read()==body and got['Metadata']==metadata[key]
   finally:got['Body'].close()
   result[key]={'etag':got['ETag'],'last_modified':got['LastModified'].isoformat(),'metadata':got['Metadata'],'content_type':got['ContentType'],'sha256':hashlib.sha256(body).hexdigest()}
  assert listing(s3)==sorted(bodies)
  return result
 def benchmark(phase):
  timings=[]
  for i in range(6):
   key='bench/'+phase+'/'+secrets.token_hex(5);body=os.urandom(131+i);started=time.perf_counter();put(key,body);timings.append(time.perf_counter()-started)
  listing_times=[]
  for _ in range(3):
   started=time.perf_counter();assert listing(s3)==sorted(bodies);listing_times.append(time.perf_counter()-started)
  ordered=sorted(timings);record_native({'kind':'native_rgws3_latency_samples','phase':phase,'objects':len(bodies),'put_seconds':timings,'put_p50_seconds':ordered[math.ceil(.5*len(ordered))-1],'put_p95_seconds':ordered[math.ceil(.95*len(ordered))-1],'complete_paginated_list_seconds':listing_times,'production_performance_certified':False})
 # Warm up real pool creation outside latency samples, then retain the sentinel.
 put('unknown-retained/'+secrets.token_hex(5),b'preserve sentinel')
 for _ in range(32+secrets.randbelow(17)):put('objects/'+secrets.token_hex(7),os.urandom(secrets.choice((0,137,1031,4097))))
 benchmark('before');original=snapshot();time.sleep(1.1)
 starting=native('bucket','stats','--bucket',bucket);assert starting['num_shards']==1
 for repeat in range(2):
  keys_before=listing(s3);state_before=snapshot();stats_before=native('bucket','stats','--bucket',bucket);receipts=[]
  def admin(*args):
   args=tuple(map(str,args));allowed=[('bucket','stats','--bucket',bucket),('bucket','reshard','--bucket',bucket,'--num-shards',str(target)),('reshard','status','--bucket',bucket)]+[('bi','list','--bucket',bucket,'--shard-id',str(i))for i in range(target)]
   assert args in allowed,'only native owned-bucket stats/index/approved reshard operations allowed'
   receipt={'argv':args};receipts.append(receipt)
   try:value=native(*args)
   except RuntimeError as error:receipt['native_error']=str(error);raise
   receipt['value']=copy.deepcopy(value);return copy.deepcopy(value)
  loan=get_session().create_client('s3',region_name='us-east-1',endpoint_url='http://127.0.0.1:'+str(c.http_port),aws_access_key_id=c.access,aws_secret_access_key=c.secret,config=Config(s3={'addressing_style':'path'},proxies={},connect_timeout=2,read_timeout=6,retries={'max_attempts':0}))
  def scope_and_page_limit(params,model,**kwargs):
   assert model.name in ('ListObjectsV2','GetObject','HeadObject')and params.get('Bucket')==bucket,'student S3 view is read-only and scoped to owned bucket'
   if model.name=='ListObjectsV2':params['MaxKeys']=min(params.get('MaxKeys',1000),7)
  loan.meta.events.register('before-parameter-build.s3',scope_and_page_limit)
  try:
   for invalid in (0,False,'5'):
    before_invalid=native('bucket','stats','--bucket',bucket)
    try:task.reshard(admin,loan,bucket,invalid)
    except ValueError:pass
    else:raise AssertionError('invalid unapproved shard target accepted')
    assert native('bucket','stats','--bucket',bucket)==before_invalid,'rejected shard target changed bucket'
   result=task.reshard(admin,loan,bucket,target)
   before_shrink=native('bucket','stats','--bucket',bucket)
   try:task.reshard(admin,loan,bucket,2)
   except ValueError:pass
   else:raise AssertionError('legal integer shrink target was accepted')
   assert native('bucket','stats','--bucket',bucket)==before_shrink,'rejected shrink changed index/header generation'
  finally:loan.close()
  stats=[row for row in receipts if row['argv'][:2]==('bucket','stats')];repairs=[row for row in receipts if row['argv'][:2]==('bucket','reshard')];statuses=[row for row in receipts if row['argv'][:2]==('reshard','status')]
  assert len(stats)>=2 and statuses,'native before/after stats and reshard status evidence required'
  if repeat==0:assert repairs and receipts.index(stats[0])<receipts.index(repairs[0])<receipts.index(stats[-1]),'diagnosis must precede actual official reshard'
  else:assert not repairs,'repeat must not perform another reshard'
  actual=native('bucket','stats','--bucket',bucket);assert actual['num_shards']==target and actual['owner']==starting['owner']and actual['bucket']==bucket
  if repeat:assert actual['index_generation']==stats_before['index_generation'],'repeat changed native index generation'
  by_shard={}
  for i in range(target):
   matches=[row for row in receipts if row['argv']==('bi','list','--bucket',bucket,'--shard-id',str(i))];assert matches,'missing actual shard evidence';by_shard[str(i)]=matches[-1]['value']
  expected={'before_stats':stats[0]['value'],'after_stats':stats[-1]['value'],'before_keys':keys_before,'after_keys':sorted(bodies),'shard_entries':by_shard,'reshard_status':statuses[-1]['value'],'production_performance_certified':False}
  assert canon(result)==canon(expected),'returned evidence differs from raw native observations'
  observed_index=[row['entry']['name']for i in range(target)for row in native('bi','list','--bucket',bucket,'--shard-id',str(i))if row['type']=='plain'and row['entry']['exists']]
  assert sorted(observed_index)==sorted(bodies),'native index lost/duplicated objects'
  actual_status=native('reshard','status','--bucket',bucket)
  assert len(actual_status)==target and all(row['reshard_status']=='not-resharding'for row in actual_status),'native reshard has not finished across every shard'
  assert snapshot()==state_before,'reshard must preserve real object heads/bytes/metadata and sentinel'
  record_native({'kind':'official_native_bucket_index_reshard_verified','repeat':repeat,'before_shards':stats[0]['value']['num_shards'],'after_shards':actual['num_shards'],'index_generation':actual['index_generation'],'counts':[len(by_shard[str(i)])for i in range(target)],'receipts':receipts})
  if repeat==0:
   benchmark('after');current=snapshot();assert all(current[key]==value for key,value in original.items()),'post-reshard benchmark changed original objects'
 for key in bodies:s3.delete_object(Bucket=bucket,Key=key)
 s3.delete_bucket(Bucket=bucket)
assert not c.root.exists()and all(p.poll()is not None for p in c.processes),'owned native resources leaked'
